var SPACING_PRESET=[2,4,8,12,16,24,32,48,64,96];
function spacingScale(opts){
  opts=opts||{}; var steps=opts.steps!=null?opts.steps:8; if(steps<1)steps=1; else if(steps>16)steps=16;
  var out=[];
  if(opts.mode==='linear'){
    var base=opts.base!=null?opts.base:4;
    for(var i=0;i<steps;i++) out.push({k:i+1, v:base*(i+1)});
  } else {
    var n=Math.min(steps, SPACING_PRESET.length);
    for(var j=0;j<n;j++) out.push({k:j+1, v:SPACING_PRESET[j]});
  }
  var L=[]; for(var k=0;k<out.length;k++) L.push('--space-'+out[k].k+': '+out[k].v+'px;');
  return L.join('\n');
}

var EXPORTS={spacingScale:spacingScale};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.SpacingForgePure = EXPORTS; }
